import re
from dataclasses import dataclass, field
from typing import Optional

# Release headings: "## [2.4.0] - 2024-05-02" or, for the unreleased section,
# "## [Unreleased]" with no date.
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# HTML comments may span several lines. A comment that occupies the rest of a
# line takes the whitespace in front of it with it, so no trailing whitespace
# is left behind.
_COMMENT_TO_EOL = re.compile(r"[ \t]*<!--.*?-->[ \t]*(?=\n|\Z)", re.DOTALL)
_COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def _strip_comments(text):
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = _COMMENT_TO_EOL.sub("", text)
    return _COMMENT.sub("", text)


def parse_changelog(text):
    releases = []
    current = None
    # Comments are removed first so that a comment containing a "## " line
    # cannot be mistaken for a heading.
    for line in _strip_comments(text).split("\n"):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                # Some other second-level section (not a release): its body
                # must not be attributed to the release above it.
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    cleaned = []
    for line in lines:
        if line.strip() == "":
            if cleaned and cleaned[-1] != "":
                cleaned.append("")
        else:
            cleaned.append(line)
    while cleaned and cleaned[-1] == "":
        cleaned.pop()
    while cleaned and cleaned[0] == "":
        cleaned.pop(0)
    return cleaned


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            if release.date is None:
                header = f"# {release.version}"
            else:
                header = f"# {release.version} ({release.date})"
            body = _clean_body(release.body)
            return "\n".join([header, ""] + body) + "\n"
    raise LookupError(version)

